INSERT INTO warehouse."master"."DIM_DATE_YEAR_ID" ("YEAR_ID") SELECT DISTINCT incoming."YEAR_ID" FROM (SELECT "YEAR_ID", "MONTH_ID", "DAY_ID", "DAY_NAME" FROM warehouse."ingest"."DIM_DATE") AS incoming LEFT JOIN warehouse."master"."DIM_DATE_YEAR_ID" AS existing ON incoming."YEAR_ID" = existing."YEAR_ID" WHERE existing."YEAR_ID" IS NULL AND incoming."YEAR_ID" IS NOT NULL;
